  if (operation === "rebuild-calendar") {
    replaceCalendar(destination, projected);
    console.log(JSON.stringify({edition:source.edition, rows:projected.length}));
    return;
  }
  throw new Error("unknown calendar operation " + operation);
}

function main(argv) {
