import test from "node:test";
import assert from "node:assert/strict";
import {planner, apply} from "./replay.mjs";

const catalog = () => ({default:5, studios:new Map([["orchid",8], ["iris",3]])});
const request = (id, extra = {}) => ({service:"studio", action:"book", id,
  tenant:"orchid", day:"2025-04-02", units:7, ...extra});

test("Studio accounts per tenant and day, including allocations below the default", () => {
  const dispatch = planner(catalog());
  assert.deepEqual(dispatch(request("a")), {status:"booked", id:"a", remaining:1});
  assert.deepEqual(dispatch(request("b", {units:2})), {status:"full", id:"b", remaining:1});
  assert.equal(dispatch(request("c", {day:"2025-04-03", units:8})).status, "booked");
  assert.equal(dispatch(request("d", {tenant:"iris", units:4})).status, "full");
  assert.equal(dispatch(request("e", {tenant:"iris", units:3})).status, "booked");
  assert.equal(dispatch(request("f", {tenant:"lily", units:6})).status, "full");
  assert.equal(dispatch(request("g", {tenant:"lily", units:5})).status, "booked");
  assert.equal(dispatch(request("h", {service:"archive"})).status, "full");
  assert.equal(dispatch(request("i", {service:"archive", units:5})).status, "booked");
});

test("Studio retains replay, conflict, cancellation and journal semantics", () => {
  const dispatch = planner(catalog());
  const a = request("a", {units:8});
  assert.equal(dispatch(a).status, "booked");
  assert.equal(dispatch(a).status, "replay");
  assert.equal(dispatch({...a, units:9}).status, "conflict");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"a"}).status, "cancelled");
  assert.equal(dispatch(a).status, "cancelled");
  assert.equal(dispatch(request("b", {units:8})).status, "booked");
  const summary = dispatch({service:"studio", action:"summary"});
  assert.deepEqual(summary.occupied.map(row => row.id), ["b"]);
  assert.deepEqual(summary.events.map(row => row.type), ["booked", "cancelled", "booked"]);
  assert.deepEqual(apply(dispatch, request("invalid", {units:0})), {status:"invalid", field:"units"});
});

test("monthly renewals inherit tenant and units and share Studio admission", () => {
  const dispatch = planner(catalog());
  dispatch(request("old"));
  const renewal = {service:"studio", action:"renew", previous:"old", id:"new", day:"2025-05-02"};
  assert.deepEqual(dispatch(renewal), {status:"booked", id:"new", remaining:1});
  assert.equal(dispatch(renewal).status, "replay");
  assert.equal(dispatch({...renewal, units:6}).status, "conflict");
  assert.deepEqual(dispatch({...renewal, id:"overflow", units:2}),
    {status:"full", id:"overflow", remaining:1});
  assert.equal(dispatch({...renewal, id:"last", units:1}).status, "booked");
  dispatch({service:"studio", action:"cancel", id:"new"});
  assert.equal(dispatch(renewal).status, "cancelled");
  dispatch({service:"studio", action:"cancel", id:"old"});
  assert.deepEqual(dispatch({...renewal, id:"after"}), {status:"missing", id:"old"});
  assert.equal(dispatch({...renewal, previous:"absent"}).status, "missing");
});

test("fallback and low-cap renewals obey their allocations; Archive retains the default", () => {
  const dispatch = planner(catalog());
  for (const [tenant, units, service] of [["lily",5,"studio"], ["iris",3,"studio"], ["orchid",5,"archive"]]) {
    dispatch(request(tenant, {tenant, units, service}));
    const renewal = {service, action:"renew", previous:tenant, id:tenant + "-next", day:"2025-05-02"};
    assert.equal(dispatch({...renewal, units:units + 1}).status, "full");
    assert.equal(dispatch(renewal).remaining, 0);
  }
});

